/*
 * [演算法說明]
 * 這是一個動態規劃 (DP) 與概率問題。
 * 
 * 狀態定義：
 * dp[i][j] 表示長度為 i 且最後一個數字是 j 的「緊湊詞」(tight words) 的個數（或機率）。
 * 為了計算百分比，我們可以直接計算機率。
 * 
 * 轉移方程：
 * dp[i][j] = (dp[i-1][j-1] + dp[i-1][j] + dp[i-1][j+1]) / (k + 1)
 * 其中要注意邊界條件（j-1 >= 0, j+1 <= k）。
 * 
 * 初始狀態：
 * dp[1][j] = 1.0 / (k + 1) 對於所有 0 <= j <= k。
 * 
 * 最後結果：
 * sum(dp[n][j]) 對所有 0 <= j <= k，再乘以 100。
 */

#include <iostream>
#include <vector>
#include <iomanip>

using namespace std;

int main() {
    int k, n;
    while (cin >> k >> n) {
        if (n == 0) {
            cout << fixed << setprecision(5) << 0.0 << endl;
            continue;
        }
        vector<vector<double>> dp(n + 1, vector<double>(k + 1, 0.0));

        for (int j = 0; j <= k; ++j) {
            dp[1][j] = 100.0 / (k + 1);
        }

        for (int i = 2; i <= n; ++i) {
            for (int j = 0; j <= k; ++j) {
                double prob = dp[i-1][j];
                if (j > 0) prob += dp[i-1][j-1];
                if (j < k) prob += dp[i-1][j+1];
                dp[i][j] = prob / (k + 1);
            }
        }

        double total_percentage = 0;
        for (int j = 0; j <= k; ++j) {
            total_percentage += dp[n][j];
        }
        cout << fixed << setprecision(5) << total_percentage << endl;
    }
    return 0;
}
